// Builds a "open in Maps" link for a restaurant location string from the menu
// data. Uses an exact pin when the location is in MAP_COORDS (generated by
// scripts/build-map-coords.js), otherwise a maps search near the resort.
// Loaded as a plain <script> in the browser (exposes window.mapLinkFor) and
// required directly by the Node tests.
(function(root) {
  // Rough center of the resort, used to bias Apple Maps searches.
  const RESORT_SLL = '33.8100,-117.9190';
  const NO_PIN = /^(various\b|outdoor vending\b|park-wide\b)/i;

  // "Napa Rose — Grand Californian Hotel / Pool Bar" -> "Napa Rose — Grand Californian Hotel"
  const firstPlace = (loc) => loc.split(' / ')[0].trim();
  // "Napa Rose — Grand Californian Hotel" -> "Napa Rose"
  const shortName = (place) => place.split(' — ')[0].trim();

  function searchQuery(loc) {
    const place = firstPlace(loc);
    const near = place.match(/^.+? near (.+)$/i);
    return (near ? near[1] : place).replace(/ — /g, ', ');
  }

  function mapLinkFor(loc, opts) {
    if (!loc || NO_PIN.test(loc)) return null;
    const coords = (opts && opts.coords) || {};
    const apple = !!(opts && opts.apple);
    const pin = coords[loc];

    if (pin) {
      const [lat, lng] = pin;
      return {
        exact: true,
        href: apple
          ? 'https://maps.apple.com/?ll=' + lat + ',' + lng + '&q=' + encodeURIComponent(shortName(firstPlace(loc)))
          : 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(lat + ',' + lng),
      };
    }

    const q = searchQuery(loc);
    return {
      exact: false,
      href: apple
        ? 'https://maps.apple.com/?q=' + encodeURIComponent(q) + '&sll=' + RESORT_SLL
        : 'https://www.google.com/maps/search/?api=1&query=' + encodeURIComponent(q + ', Anaheim, CA'),
    };
  }

  if (typeof module !== 'undefined' && module.exports) {
    module.exports = { mapLinkFor };
  } else {
    root.mapLinkFor = mapLinkFor;
  }
})(this);
